        "javascript": "function allPathsSourceTarget(n, edges) {\n    const adj = Array.from({ length: n }, () => []);\n    for (const [u, v] of edges) {\n        adj[u].push(v);\n        adj[v].push(u);\n    }\n    const visited = new Set();\n    let components = 0;\n    function dfs(node) {\n        visited.add(node);\n        for (const nei of adj[node]) if (!visited.has(nei)) dfs(nei);\n    }\n    for (let i = 0; i < n; i++) {\n        if (!visited.has(i)) {\n            components++;\n            dfs(i);\n        }\n    }\n    return components;\n}"
