      "polyglotCode": {
        "python": "    def equationsPossible(self, n: int, edges: list[list[int]]) -> int:\n        adj = [[] for _ in range(n)]\n        for u, v in edges:\n            adj[u].append(v); adj[v].append(u)\n        visited = set()\n        def dfs(node):\n            visited.add(node)\n            for nei in adj[node]:\n                if nei not in visited: dfs(nei)\n        comp = 0\n        for i in range(n):\n            if i not in visited:\n                comp += 1; dfs(i)\n        return comp",
        "java": "    public int equationsPossible(int n, int[][] edges) {\n        List<List<Integer>> adj = new ArrayList<>();\n        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());\n        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }\n        boolean[] vis = new boolean[n]; int count = 0;\n        for (int i = 0; i < n; i++) {\n            if (!vis[i]) { count++; dfs(i, adj, vis); }\n        }\n        return count;\n    }\n    private void dfs(int u, List<List<Integer>> adj, boolean[] vis) {\n        vis[u] = true;\n        for (int v : adj.get(u)) if (!vis[v]) dfs(v, adj, vis);\n    }",
        "cpp": "    int equationsPossible(int n, vector<vector<int>>& edges) {\n        vector<vector<int>> adj(n);\n        for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }\n        vector<bool> vis(n, false); int count = 0;\n        auto dfs = [&](auto& self, int u) -> void {\n            vis[u] = true;\n            for (int v : adj[u]) if (!vis[v]) self(self, v);\n        };\n        for (int i = 0; i < n; i++) if (!vis[i]) { count++; dfs(dfs, i); }\n        return count;\n    }",
        "javascript": "function equationsPossible(n, edges) {\n    const adj = Array.from({ length: n }, () => []);\n    for (const [u, v] of edges) {\n        adj[u].push(v);\n        adj[v].push(u);\n    }\n    const visited = new Set();\n    let components = 0;\n    function dfs(node) {\n        visited.add(node);\n        for (const nei of adj[node]) if (!visited.has(nei)) dfs(nei);\n    }\n    for (let i = 0; i < n; i++) {\n        if (!visited.has(i)) {\n            components++;\n            dfs(i);\n        }\n    }\n    return components;\n}"
      }
